const ar={skip:'انتقل للمحتوى',home:'الرئيسية',services:'خدماتنا',work:'من شغلنا',contact:'تواصل معانا',book:'احجز دلوقتي ↗',tagline:'تعديل وأداء السيارات',headline:'كل اللي عربيتك <em>محتاجاه.</em>',intro:'حماية السيارات، الإكسسوارات، تظليل الزجاج، العناية بالسيارات، الإضاءة، والدهان الكامل.',whatsapp:'تواصل على واتساب',explore:'شوف شغلنا',concept:'تصوّر فني للجراج',discover:'اكتشف VOLT X',serviceLabel:'01 / خدماتنا',serviceHeading:'كل اللي عربيتك<br><span>محتاجاه.</span>',everything:'كل اللي عربيتك محتاجاه',protection:'حماية السيارات',accessories:'إكسسوارات السيارات',tinting:'تظليل الزجاج',detailing:'العناية التفصيلية بالسيارات',lighting:'إضاءة السيارات',painting:'دهان السيارة بالكامل',ppfLabel:'02 / حماية الطلاء',ppfHeading:'أفلام حماية<br><em>الطلاء PPF</em>',ppfCopy:'نظرة أقرب على أفلام الحماية من خلال المواد الدعائية لـ VOLT X.',ask:'اسألنا عن PPF',viewCollection:'شوف الصور ↗',workLabel:'03 / معرض الصور',galleryNote:'تصميمات دعائية أصلية.<br>اضغط على الصورة لعرضها كاملة.',ppfCaption:'PPF / تصميم دعائي',aflamCaption:'أفلام الحماية / تصميم دعائي',disclosure:'تصميمات دعائية مركّبة معروضة كما وردت، وليست مقارنة تفاعلية قبل وبعد.',contactLabel:'04 / خلينا نتكلم',contactHeading:'عربيتك.<br><em>خطوتك الجاية.</em>',touch:'تواصل معانا',call:'اتصل بـ VOLT X',find:'موقع VOLT X',maps:'افتح في خرائط جوجل',instagram:'إنستجرام ↗',facebook:'فيسبوك ↗',top:'ارجع للأعلى ↑',unofficial:'تصوّر غير رسمي لتصميم موقع — أُعدّ لأغراض العرض فقط.',close:'إغلاق ×',previous:'→ السابقة',next:'التالية ←',ppfAlt:'تصميم دعائي من VOLT X لأفلام الحماية، يعرض صورتين لسيارة',aflamAlt:'تصميم دعائي مركّب من VOLT X لأفلام حماية الطلاء'};
const english={};document.querySelectorAll('[data-t]').forEach(el=>english[el.dataset.t]=el.innerHTML);
const altEnglish={};document.querySelectorAll('[data-alt]').forEach(el=>altEnglish[el.dataset.alt]=el.alt);
let lang='en';try{lang=localStorage.getItem('voltx-language')==='ar'?'ar':'en'}catch{}
const menu=document.querySelector('#menu'),nav=document.querySelector('#navigation'),toggle=document.querySelector('#language'),dialog=document.querySelector('#lightbox');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label',lang==='ar'?'فتح القائمة':'Open menu')}
function setLanguage(value){lang=value;document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(el=>el.innerHTML=(lang==='ar'?ar:english)[el.dataset.t]);document.querySelectorAll('[data-alt]').forEach(el=>el.alt=(lang==='ar'?ar:altEnglish)[el.dataset.alt]);toggle.innerHTML=lang==='ar'?'English <span>EN</span>':'العربية <span>AR</span>';toggle.lang=lang==='ar'?'en':'ar';toggle.setAttribute('aria-label',lang==='ar'?'Switch to English':'التبديل إلى العربية');nav.setAttribute('aria-label',lang==='ar'?'القائمة الرئيسية':'Main navigation');document.querySelector('footer nav').setAttribute('aria-label',lang==='ar'?'روابط التذييل':'Footer');document.querySelectorAll('.gallery-item').forEach(el=>el.setAttribute('aria-label',(lang==='ar'?'افتح: ':'Open: ')+(lang==='ar'?ar:english)[el.dataset.image+'Caption']));closeMenu();try{localStorage.setItem('voltx-language',lang)}catch{}}
setLanguage(lang);toggle.addEventListener('click',()=>setLanguage(lang==='en'?'ar':'en'));
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',lang==='ar'?(open?'إغلاق القائمة':'فتح القائمة'):(open?'Close menu':'Open menu'))});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu()}});document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu()});
const images=['ppf','aflam'];let index=0;let opener=null;
function showImage(){const name=images[index];const img=document.querySelector('#lightbox-image');img.src='./assets/'+name+'-full.webp';img.alt=(lang==='ar'?ar:altEnglish)[name+'Alt'];document.querySelector('#lightbox-caption').textContent=(lang==='ar'?ar:english)[name+'Caption']}
document.querySelectorAll('.gallery-item').forEach(button=>button.addEventListener('click',()=>{opener=button;index=images.indexOf(button.dataset.image);showImage();dialog.showModal();document.body.classList.add('modal-open')}));
function next(step){index=(index+step+images.length)%images.length;showImage()}
document.querySelector('#close').addEventListener('click',()=>dialog.close());document.querySelector('#previous').addEventListener('click',()=>next(-1));document.querySelector('#next').addEventListener('click',()=>next(1));dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');opener?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight')next(lang==='ar'?-1:1);if(e.key==='ArrowLeft')next(lang==='ar'?1:-1)});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('reveal');observer.unobserve(entry.target)}})},{threshold:.12});document.querySelectorAll('.section-heading,.service,.ppf-copy').forEach(el=>observer.observe(el))}

